245	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
246	        if (hasEmail) {
247	            level++;
248	        }
249	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
250	        if (noNamesakes) {
251	            level++;
252	        }
253	        boolean tenured = owner.getRegistrationDate() != null
254	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365;
255	        if (tenured) {
