270	        }
271	        int sum = 0;
272	        boolean dbl = true;
273	        String code = owner.getCustomerCode();
274	        for (int i = code.length() - 1; i >= 0; i--) {
275	            char c = code.charAt(i);
276	            if (c < '0' || c > '9') {
277	                continue;
278	            }
279	            int d = c - '0';
280	            if (dbl) {
281	                d *= 2;
282	                if (d > 9) {
283	                    d -= 9;
284	                }
285	            }
286	            sum += d;
287	            dbl = !dbl;
288	        }
289	        return (10 - (sum % 10)) % 10;
290	    }
