311	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
312	        ownerPageDto.setPage(ownerPage.getNumber());
313	        ownerPageDto.setSize(ownerPage.getSize());
314	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
315	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
316	        return ownerPageDto;
317	    }
318	}
